// Minimal Gemini (Google AI Studio) client over the REST API.
// No SDK dependency — uses global fetch (Node >= 18).
//
// Tool/function-calling protocol (v1beta generateContent):
//   - tools: [{ functionDeclarations: [...] }]
//   - model returns parts with { functionCall: { name, args } }
//   - we reply with a content { role: "user", parts: [{ functionResponse: {...} }] }

const BASE = "https://generativelanguage.googleapis.com/v1beta";

export class GeminiError extends Error {}

/**
 * One turn of generation. Returns the raw candidate content
 * { role: "model", parts: [...] } plus any text / functionCalls extracted.
 */
export async function generate({
  model,
  apiKey,
  systemInstruction,
  contents,
  tools,
  temperature = 1.0,
  maxOutputTokens = 2048,
  signal,
}) {
  const url = `${BASE}/models/${model}:generateContent?key=${apiKey}`;
  const body = {
    contents,
    generationConfig: { temperature, maxOutputTokens },
  };
  if (systemInstruction) body.systemInstruction = { parts: [{ text: systemInstruction }] };
  if (tools) body.tools = tools;

  let res;
  for (let attempt = 0; attempt < 5; attempt++) {
    res = await fetch(url, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify(body),
      signal,
    });
    if (res.status === 429 || res.status >= 500) {
      const wait = 2 ** attempt * 1000 + Math.floor(attempt * 137);
      await new Promise((r) => setTimeout(r, wait));
      continue;
    }
    break;
  }
  if (!res.ok) {
    const txt = await res.text().catch(() => "");
    throw new GeminiError(`Gemini ${res.status}: ${txt.slice(0, 500)}`);
  }
  const data = await res.json();
  const cand = data.candidates?.[0];
  const content = cand?.content ?? { role: "model", parts: [] };
  const parts = content.parts ?? [];
  const text = parts.filter((p) => p.text).map((p) => p.text).join("");
  const functionCalls = parts
    .filter((p) => p.functionCall)
    .map((p) => p.functionCall);
  const finishReason = cand?.finishReason ?? "UNKNOWN";
  return { content, text, functionCalls, finishReason };
}


