// most severe examples.
//
// Usage:
//   GEMINI_API_KEY=... node src/run.js [flags]
// Flags:
//   --model <id>        Gemini model        (default gemini-2.5-flash)
//   --judge <id>        Anthropic judge     (default claude-sonnet-4-6; "none" = regex only)
//   --n <int>           rollouts per scenario per temperature (default 30)
//   --turns <int>       max turns per rollout (default 12)
//   --temps <list>      comma temps         (default 0.7,1.0)
//   --scenarios <list>  comma scenario ids  (default all)
//   --concurrency <int> parallel rollouts   (default 6)
//   --top <int>         examples in report  (default 15)
//   --out <dir>         output dir          (default results)
import { writeFileSync, mkdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { SCENARIOS, getScenario } from "./scenarios.js";
import { runRollout } from "./harness.js";
import { judgeTranscript } from "./judge.js";

function parseArgs(argv) {
  const a = {};
  for (let i = 0; i < argv.length; i++) {
    if (argv[i].startsWith("--")) a[argv[i].slice(2)] = argv[i + 1], i++;
  }
  return a;
}

// Tiny .env loader (no dependency).
function loadEnv() {
  try {
    for (const line of readFileSync(".env", "utf8").split("\n")) {
      const m = line.match(/^\s*([A-Z0-9_]+)\s*=\s*(.*)\s*$/);
      if (m && !process.env[m[1]]) process.env[m[1]] = m[2].replace(/^["']|["']$/g, "");
    }
  } catch {}
}

async function pool(items, concurrency, worker) {
  const results = new Array(items.length);
  let next = 0;
  const runners = Array.from({ length: Math.min(concurrency, items.length) }, async () => {
    while (next < items.length) {
      const i = next++;
      results[i] = await worker(items[i], i);
    }
  });
  await Promise.all(runners);
  return results;
}

