    n: parseInt(args.n || "30", 10),
    turns: parseInt(args.turns || "12", 10),
    temps: (args.temps || "0.7,1.0").split(",").map(Number),
    scenarioIds: args.scenarios ? args.scenarios.split(",") : SCENARIOS.map((s) => s.id),
